exercises.tests:
def test_quotient():
    assert quotient == 3, f"ожидалось quotient=3, получено {quotient}"


def test_remainder():
    assert remainder == 2, f"ожидалось remainder=2, получено {remainder}"


def test_power():
    assert power == 289, f"ожидалось power=289, получено {power}"

def test_total_value():
    assert total == 2156.0, f"ожидалось 2156.0, получено {total}"


def test_total_is_rounded():
    assert round(total, 2) == total, "результат должен быть округлён до копеек (2 знака после запятой)"


def test_is_ok_status_true_for_304():
    assert is_ok_status is True, "304 входит в разрешённые статусы, ожидается True"


def test_is_ok_status_is_bool():
    assert isinstance(is_ok_status, bool), "is_ok_status должен быть именно bool (True/False), а не число"

def test_effective_sla():
    assert effective_sla == 600.0, f"при is_retry=True SLA увеличивается на 20% (500 * 1.2 = 600), получено {effective_sla}"


def test_is_within_sla_true():
    assert is_within_sla is True, "580 <= 600, значит is_within_sla должен быть True"


def test_is_within_sla_is_bool():
    assert isinstance(is_within_sla, bool), "is_within_sla должен быть именно bool"

def test_naive_equal_is_false():
    assert naive_equal is False, "из-за погрешности хранения float, 0.1 + 0.1 + 0.1 не равно 0.3 напрямую через =="


def test_safe_equal_is_true():
    assert safe_equal is True, "сравнение через допустимую погрешность (abs(a - b) < 1e-9) должно считать числа равными"


def test_naive_and_safe_differ():
    assert naive_equal != safe_equal, "naive_equal и safe_equal должны отличаться — в этом весь смысл задания"
